<?php
/** TEMP PS S1691 m — (1) deploy petshop-dropship-matomumas.php v1.0.0 + heartbeat; (2) dry-run peržiūra; (3) tikras perkėlimas; (4) E2E su testine preke #34889 + realios paslėptos prekės 200 patikra. */
add_action('init', function(){
  if (!isset($_GET['ps_s1691m'])) return; global $wpdb; $p=$wpdb->prefix; $o=array(); $wpdb->suppress_errors(true); $f=$_GET['ps_s1691m'];
  $path=WPMU_PLUGIN_DIR.'/petshop-dropship-matomumas.php';
  if ($f==='1'){
    $c=base64_decode(''); $o['md5_turinys']=md5($c);
    try { token_get_all($c, TOKEN_PARSE); } catch (Throwable $e) { $o['PARSE']=$e->getMessage(); }
    if (empty($o['PARSE'])){ if (file_exists($path)) $o['buvo']=md5_file($path); file_put_contents($path,$c); $o['md5_failas']=md5_file($path);
      $r=wp_remote_get(home_url('/'),array('timeout'=>25,'sslverify'=>false)); $code=is_wp_error($r)?0:wp_remote_retrieve_response_code($r); $o['heartbeat']=$code;
      if ($code>=500||$code===0){ unlink($path); $o['ROLLBACK']='failas pašalintas'; } }
  }
  if ($f==='2'){ $o['klase']=class_exists('Petshop_Dropship_Matomumas'); $o['cron']=wp_next_scheduled('ps_dropship_matomumas_valanda'); $o['dry']=Petshop_Dropship_Matomumas::perziureti(true);
    // kiek liktų matomų su išimtimi ir kodėl
    $in="'vf','zb'"; $ids=$wpdb->get_col("SELECT DISTINCT ps.ID FROM {$p}posts ps JOIN {$p}postmeta s ON s.post_id=ps.ID AND s.meta_key='_ps_sandelis' AND s.meta_value IN ($in) JOIN {$p}postmeta st ON st.post_id=ps.ID AND st.meta_key='_stock_status' AND st.meta_value='outofstock' WHERE ps.post_type='product' AND ps.post_status='publish'");
    $isim=array(); foreach ($ids as $id){ $k=Petshop_Dropship_Matomumas::turi_istorija($id); if ($k) $isim[]=$id.':'.$k.':'.mb_substr(get_the_title($id),0,40); } $o['isimtys']=$isim; $o['isimciu']=count($isim); $o['outofstock_dropship']=count($ids);
  }
  if ($f==='3'){ $o['rez']=Petshop_Dropship_Matomumas::perziureti(false); $o['hidden_dabar']=$wpdb->get_var("SELECT COUNT(*) FROM {$p}postmeta WHERE meta_key='_ps_dropship_paslepta' AND meta_value='1'");
    $o['bak_opcija']=update_option('ps_s1691_paslepta_bak', $wpdb->get_col("SELECT post_id FROM {$p}postmeta WHERE meta_key='_ps_dropship_paslepta' AND meta_value='1'"), false); }
  if ($f==='4'){ $pid=34889; $pr=wc_get_product($pid); $o['test_pries']=array('status'=>get_post_status($pid),'stock'=>$pr?$pr->get_stock_status():null,'sandelis'=>get_post_meta($pid,'_ps_sandelis',true),'vis'=>$pr?$pr->get_catalog_visibility():null);
    $bak=$o['test_pries']; update_post_meta($pid,'_ps_sandelis','vf'); wp_update_post(array('ID'=>$pid,'post_status'=>'publish')); $pr=wc_get_product($pid); $pr->set_manage_stock(true); $pr->set_stock_quantity(0); $pr->set_stock_status('outofstock'); $pr->save();
    $o['e2e_1_nera']=array('spresti'=>Petshop_Dropship_Matomumas::spresti($pid),'vis'=>wc_get_product($pid)->get_catalog_visibility(),'meta'=>get_post_meta($pid,'_ps_dropship_paslepta',true));
    $pr=wc_get_product($pid); $pr->set_stock_quantity(3); $pr->set_stock_status('instock'); $pr->save(); // kablys turi atidengti pats
    $o['e2e_2_grizo_kablys']=array('vis'=>wc_get_product($pid)->get_catalog_visibility(),'meta'=>get_post_meta($pid,'_ps_dropship_paslepta',true),'zurnalas'=>get_option('ps_dropship_matomumas_pask'));
    $pr=wc_get_product($pid); $pr->set_stock_quantity(0); $pr->set_stock_status('outofstock'); $pr->save(); // kablys turi paslėpti pats
    $o['e2e_3_dingo_kablys']=array('vis'=>wc_get_product($pid)->get_catalog_visibility(),'meta'=>get_post_meta($pid,'_ps_dropship_paslepta',true));
    // atstatymas
    Petshop_Dropship_Matomumas::atidengti($pid); if ($bak['sandelis']!=='') update_post_meta($pid,'_ps_sandelis',$bak['sandelis']); else delete_post_meta($pid,'_ps_sandelis'); wp_update_post(array('ID'=>$pid,'post_status'=>$bak['status'])); $pr=wc_get_product($pid); $pr->set_stock_quantity(0); $pr->set_stock_status('outofstock'); $pr->save();
    $pr=wc_get_product($pid); $o['test_po']=array('status'=>get_post_status($pid),'stock'=>$pr->get_stock_status(),'sandelis'=>get_post_meta($pid,'_ps_sandelis',true),'vis'=>$pr->get_catalog_visibility(),'meta'=>get_post_meta($pid,'_ps_dropship_paslepta',true));
    // reali paslėpta prekė: URL 200, nėra kataloge
    $hid=$wpdb->get_var("SELECT post_id FROM {$p}postmeta WHERE meta_key='_ps_dropship_paslepta' AND meta_value='1' ORDER BY post_id LIMIT 1");
    if ($hid){ $u=get_permalink($hid); $r=wp_remote_get($u,array('timeout'=>25,'sslverify'=>false)); $body=is_wp_error($r)?'':wp_remote_retrieve_body($r); $o['reali']=array('id'=>$hid,'url'=>$u,'http'=>is_wp_error($r)?0:wp_remote_retrieve_response_code($r),'forma_pranesti'=>strpos($body,'ps-stock-watch')!==false||stripos($body,'kai bus')!==false,'vis'=>wc_get_product($hid)->get_catalog_visibility(),'terminai'=>wp_get_object_terms($hid,'product_visibility',array('fields'=>'slugs')));
      $q=new WP_Query(array('post_type'=>'product','post_status'=>'publish','posts_per_page'=>1,'p'=>$hid,'tax_query'=>array(array('taxonomy'=>'product_visibility','field'=>'slug','terms'=>array('exclude-from-catalog'),'operator'=>'NOT IN')))); $o['reali']['kataloge']=$q->found_posts; }
  }
  header('Content-Type: application/json'); echo json_encode($o,JSON_UNESCAPED_UNICODE|JSON_PARTIAL_OUTPUT_ON_ERROR); exit;
});
